var SAMPLES=['the quick brown fox jumps over the lazy dog','pack my box with five dozen liquor jugs','how vexingly quick daft zebras jump',
'quick zephyrs blow vexing foam','waltz bad nymph for quick jigs vex'];
function pick(rng){ return SAMPLES[Math.floor(rng()*SAMPLES.length)]; }
function metrics(typed, ref, seconds){
  if(!(seconds>0)) return null;
  var correct=0; for(var i=0;i<typed.length;i++){ if(typed[i]===ref[i]) correct++; }
  var mins=seconds/60;
  var wpm = correct>0 ? (correct/5)/mins : 0;
  var acc = typed.length>0 ? correct/typed.length : 0;
  return {correct:correct, wpm:wpm, accuracy:acc};
}
var EXPORTS={pick:pick,metrics:metrics,SAMPLES:SAMPLES};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WpmForgePure = EXPORTS; }
